with unpivoted as (select * from (select id, supplier_id, cost, price from products) src unpivot (metric_value for metric in (cost, price))) select supplier_id, sort_array(collect_set(metric)) as metric_list, count(case when metric = 'price' then 1 end) as price_count, count_if(metric = 'cost') as cost_events, count(*) as event_count, sum(case when metric = 'cost' then metric_value else 0 end) as cost_metric_value, count(*) as num_rows from unpivoted group by supplier_id order by num_rows;
